            if (find(unique.begin(),unique.end(),words[i][j])==unique.end())
                unique=unique+words[i][j];
        if (unique.length()>maxu or unique.length()==maxu)
        {
            max=words[i];
            maxu=unique.length();
        }
    }
    return max;
}


